function alertReference(value){const date=new Date(value);if(Number.isNaN(date.getTime()))return 'Sin fecha';const parts=Object.fromEntries(new Intl.DateTimeFormat('en',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date).map(part=>[part.type,part.value]));return `${parts.year}${parts.month}${parts.day}-${parts.hour}${parts.minute}${parts.second}`}
