function applyUserFilters(){const search=document.querySelector('[data-user-search]'),roleFilter=document.querySelector('[data-user-role-filter]'),typeFilter=document.querySelector('[data-user-type-filter]'),homeFilter=document.querySelector('[data-user-home-filter]');if(!search||!roleFilter||!typeFilter||!homeFilter)return;let shown=0;document.querySelectorAll('[data-user-row]').forEach(row=>{const matchesSearch=`${row.dataset.userName} ${row.dataset.userEmail}`.toLocaleLowerCase('es-CO').includes(search.value.trim().toLocaleLowerCase('es-CO'));const matchesRole=roleFilter.value==='Todos'||row.dataset.userRole===roleFilter.value;const matchesType=typeFilter.value==='Todos'||row.dataset.userType.split(' / ').includes(typeFilter.value);const matchesHome=homeFilter.value==='Todos'||row.dataset.userHomes.split(', ').includes(homeFilter.value);row.hidden=!(matchesSearch&&matchesRole&&matchesType&&matchesHome);if(!row.hidden)shown++});const empty=document.querySelector('[data-user-no-results]');if(empty)empty.hidden=shown>0}
