 let stats=admin?(live?[stat('Solicitudes abiertas',showValue('requests'),'Requieren seguimiento','▤'),stat('Visitantes pendientes',showValue('visitors'),'Esperan su ingreso','♙'),stat('Préstamos solicitados',showValue('loans'),'Pendientes de asignación','▧'),stat('Inmuebles registrados',showValue('units'),'En la base de datos','⌂')]:[stat('Solicitudes abiertas',r.filter(x=>!['Resuelta','Resuelto'].includes(x.status)).length,'Datos de demostración','▤'),stat('Visitantes hoy',data.visitors.length,'Datos de demostración','♙'),stat('Reservas activas',data.reservations.length,'Datos de demostración','▧'),stat('Unidades ocupadas','186','Datos de demostración','⌂')]):guard?[stat('Visitas esperadas',data.visitors.filter(x=>x.status==='Esperado').length,'Datos de demostración','◷'),stat('Ingresos hoy',12,'Datos de demostración','↗'),stat('Novedades abiertas',data.incidents.filter(x=>x.status!=='Atendida').length,'Datos de demostración','◷'),stat('Paquetes recibidos',5,'Datos de demostración','▣')]:live?[stat('Mis solicitudes abiertas',showValue('requests'),'En seguimiento','▤'),stat('Visitantes pendientes',showValue('visitors'),'Esperan su ingreso','♙'),stat('Próximo préstamo',summary?.loading?'Cargando…':liveStats.nextLoan?esc(liveStats.nextLoan.item):'Sin asignación',summary?.loading?'Consultando reservas':liveStats.nextLoan?`${esc(liveStats.nextLoan.date)} · ${esc(liveStats.nextLoan.schedule)}`:'Reservas aprobadas','▧'),window.portalCuotaResidentStat?.()||stat('Cuota residencial','Sin registro','Periodo actual','✓')]:[stat('Mis solicitudes',r.filter(x=>x.unit==='Torre 2 · 504').length,'Datos de demostración','▤'),stat('Visitantes esperados',data.visitors.filter(x=>x.status==='Esperado'&&x.unit==='Torre 2 · 504').length,'Datos de demostración','♙'),stat('Próxima reserva','—','Datos de demostración','▧'),window.portalCuotaResidentStat?.()||stat('Cuota residencial','Sin registro','Periodo actual','✓')];
 if(guard&&live)stats=[stat('Visitas esperadas',showValue('expectedVisits'),'Autorizaciones activas','◷'),stat('Ingresos hoy',showValue('entriesToday'),'Registrados en portería','↗'),stat('Visitantes en el conjunto',showValue('visitorsInside'),'Aún no han salido','⌂'),stat('Emergencias activas',showValue('activeAlerts'),'Requieren atención','⚠')];
 const notices=live?(window.portalDashboardNotices?.()||[]):data.notices;
 let lower=guard?`<section class="panel"><div class="panel-title"><h3>Accesos esperados</h3><button class="text-link" data-go="visitantes">Ver todos →</button></div>${table(['Visitante','Unidad','Llegada','Estado','Acción'],visitorRows(data.visitors))}</section><section class="panel"><div class="panel-title"><h3>Novedades recientes</h3><button class="text-link" data-go="novedades">Ver todas →</button></div>${data.incidents.slice(0,3).map(x=>`<div class="announcement"><span class="ann-icon">◷</span><div><h4>${esc(x.title)}</h4><p>${esc(x.unit)} · ${esc(x.date)}</p></div>${badge(x.status)}</div>`).join('')}</section>`:admin?`<section class="panel"><div class="panel-title"><h3>Comunicados recientes</h3><button class="text-link" data-go="comunicados">Ver todos →</button></div>${notices.map(x=>`<article class="announcement"><span class="ann-icon">▱</span><div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div><time>${esc(x.date)}</time></article>`).join('')||'<p class="empty">No hay comunicados publicados.</p>'}</section>`:`<section class="panel"><div class="panel-title"><h3>Avisos de la comunidad</h3><button class="text-link" data-go="comunicados">Ver todos →</button></div>${notices.map(x=>`<article class="announcement"><span class="ann-icon">${x.icon||'▱'}</span><div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div><time>${esc(x.date)}</time></article>`).join('')||'<p class="empty">No hay comunicados publicados.</p>'}</section><section class="panel"><div class="panel-title"><h3>Zonas comunes y elementos</h3><button class="text-link" data-go="reservas">Ver opciones →</button></div><p class="muted">Consulta los elementos prestables, zonas comunes y sus horarios habilitados.</p></section>`;
