function requestsPage(){if(livePortal()){const filtered=filter==='Todos'?requestRecords:requestRecords.filter(item=>item.estado===filter);const rows=filtered.map(item=>`<tr data-request-search="${esc([item.asunto,item.tipo,item.descripcion,item.usuario,item.inmueble,item.fecha,item.estado,item.respuesta].join(' '))}"><td class="main-cell">${esc(item.asunto||item.tipo)}<span class="sub-cell">${esc(item.tipo)} · ${esc(item.descripcion)}</span></td><td>${role==='administrador'?`${esc(item.usuario)}<span class="sub-cell">${esc(item.inmueble)}</span>`:esc(item.inmueble)}</td><td>${esc(item.fecha)}</td><td>${badge(item.estado)}</td><td>${role==='administrador'?`<button class="text-link" data-request-manage="${esc(item.id)}">Gestionar</button>`:esc(item.respuesta||'Sin respuesta aún')}</td></tr>`).join('');const headers=role==='administrador'?['Solicitud','Residente / inmueble','Fecha de creación','Estado','Acción']:['Solicitud','Inmueble','Fecha de creación','Estado','Respuesta'];return `${head('SERVICIO A LA COMUNIDAD',role==='residente'?'Mis solicitudes':'Solicitudes',role==='residente'?'Envía una solicitud y consulta la respuesta de administración.':'Revisa las solicitudes y actualiza su estado o respuesta.',role==='residente'?'<button class="btn-primary" data-action="request">＋ Nueva solicitud</button>':'')}<div class="filter-row">${['Todos','Abierto','Resuelto'].map(x=>`<button class="filter-chip ${filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}<input id="searchRequests" class="inline-search" placeholder="⌕  Buscar solicitud…"></div>${requestError?`<p class="auth-error">No se pudieron cargar las solicitudes: ${esc(requestError)}</p>`:''}${requestsLoading?'<section class="panel">Cargando solicitudes…</section>':`<section class="panel">${table(headers,rows)}</section>`}`}let mine=role==='residente'?data.requests.filter(x=>x.unit==='Torre 2 · 504'):data.requests;let filtered=filter==='Todos'?mine:mine.filter(x=>x.status===filter);return `${head('SERVICIO A LA COMUNIDAD',role==='residente'?'Mis solicitudes':'Solicitudes',role==='residente'?'Consulta el estado de tus requerimientos.':'Seguimiento de requerimientos de los residentes.',role==='residente'?'<button class="btn-primary" data-action="request">＋ Nueva solicitud</button>':'')}<div class="filter-row">${['Todos','Pendiente','En revisión','Resuelta'].map(x=>`<button class="filter-chip ${filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}<input id="searchRequests" class="inline-search" placeholder="⌕  Buscar solicitud…"></div><section class="panel">${table(['Solicitud','Unidad','Fecha de creación','Estado','Acción'],requestRows(filtered))}</section>`}
function visitorsPage(){if(livePortal()&&window.portalVisitorsPage)return window.portalVisitorsPage();const mine=role==='residente'?data.visitors.filter(x=>x.unit==='Torre 2 · 504'):data.visitors;return `${head('CONTROL DE ACCESO',role==='residente'?'Mis visitantes':'Control de acceso',role==='residente'?'Invita personas y consulta tus autorizaciones.':'Consulta y gestiona el flujo de visitantes del conjunto.','<button class="btn-primary" data-action="visitor">＋ Registrar visitante</button>')}<div class="stats-grid">${stat('Registros de hoy',data.visitors.length,'Todos los accesos','♙')}${stat('Esperados',data.visitors.filter(x=>x.status==='Esperado').length,'Pendientes de llegada','◷')}${stat('En el conjunto',data.visitors.filter(x=>x.status==='En conjunto').length,'Visitas activas','⌂')}${stat('Unidades activas','18','Con autorizaciones hoy','▦')}</div><section class="panel">${table(['Visitante','Unidad','Fecha / hora','Estado','Acción'],visitorRows(mine))}</section>`}
function noticesPage(){if(livePortal()&&window.portalNoticesPage)return window.portalNoticesPage();return `${head('VIDA EN COMUNIDAD','Comunicados','Información y novedades de Condominio Palo Alto.',role==='administrador'?'<button class="btn-primary" data-action="notice">＋ Nuevo comunicado</button>':'')}<div class="lower-grid">${data.notices.map(x=>`<article class="panel"><div class="announcement" style="border:0"><span class="ann-icon">${x.icon}</span><div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p><p style="margin-top:12px">${esc(x.date)}</p></div></div></article>`).join('')||'<section class="panel">Aún no hay comunicados.</section>'}</div>`}
function reservationsPage(){if(livePortal())return `${head('ESPACIOS COMPARTIDOS','Zonas comunes','El inventario y los horarios se configuran en Datos básicos.')}<section class="panel"><p class="muted">Las solicitudes de préstamo ya se registran desde la cuenta del residente. La pantalla para consultar y asignar esas solicitudes desde portería está pendiente.</p>${role==='administrador'?'<button class="btn-secondary" data-go="datos-basicos">Configurar elementos y horarios</button>':''}</section>`;return `${head('ESPACIOS COMPARTIDOS','Zonas comunes','Consulta disponibilidad y administra las reservas.',role==='residente'?'<button class="btn-primary" data-action="reservation">＋ Solicitar reserva</button>':'')}<div class="section-grid">${[['Salón social','Ideal para celebraciones y reuniones.','♧'],['Terraza BBQ','Comparte una tarde al aire libre.','♨'],['Cancha múltiple','Reserva un espacio para jugar.','⌁']].map(x=>`<article class="feature-card"><span class="feature-icon">${x[2]}</span><h3>${x[0]}</h3><p>${x[1]}</p><button ${role==='administrador'?'data-demo-reservations="'+esc(x[0])+'"':'data-action="reservation"'}>${role==='administrador'?'Ver reservas':'Consultar disponibilidad →'}</button></article>`).join('')}</div><section class="panel" id="demoReservations" style="margin-top:16px"><div class="panel-title"><h3>Reservas recientes</h3></div>${table(['Espacio','Solicitante','Fecha','Estado'],data.reservations.map(x=>`<tr data-demo-reservation-row="${esc(x.title)}"><td class="main-cell">${esc(x.title)}</td><td>${esc(x.unit)}</td><td>${esc(x.date)}</td><td>${badge(x.status)}</td></tr>`).join(''))}</section>`}
