 const filters=`<div class="access-filters"><input class="inline-search" type="search" data-emergency-search value="${esc(emergencyFilters.search)}" placeholder="⌕ Buscar residente, inmueble o referencia…" aria-label="Buscar alertas"><select class="inline-search" data-emergency-type aria-label="Filtrar por tipo"><option value="Todos">Todos los tipos</option>${types.map(type=>`<option value="${esc(type)}" ${emergencyFilters.type===type?'selected':''}>${esc(type)}</option>`).join('')}</select><select class="inline-search" data-emergency-status aria-label="Filtrar por estado"><option value="Todos" ${emergencyFilters.status==='Todos'?'selected':''}>Todos los estados</option>${['Activa','Atendida'].map(status=>`<option value="${status}" ${emergencyFilters.status===status?'selected':''}>${status}</option>`).join('')}</select><span class="assembly-result-count">${filtered.length} de ${visible.length} alerta(s)</span></div>`;
