let panicSuccessAlertId='',dismissedGeneralAlertId='',lastAlarmAlertId='',panicFrame=0;
function emergencyOverlay(){
 if(role==='vigilante'){
  const alert=data.emergencyAlerts.find(item=>item.type==='Residente'&&item.status==='Activa');
  if(alert){if(lastAlarmAlertId!==alert.id){lastAlarmAlertId=alert.id;playEmergencySound()}return `<div class="emergency-overlay" role="alert"><span class="emergency-kicker">EMERGENCIA · RESIDENTE PIDE AYUDA</span><h1>${esc(alert.name)}</h1><h2>${esc(alert.unit)}</h2><p>${esc(alert.detail||'Botón de pánico activado')}</p><div class="emergency-actions"><a class="btn-call" href="tel:${esc(alert.phone)}">☎ Llamar · ${esc(alert.phone)}</a><button class="btn-attended" data-ack-alert="${esc(alert.id)}">Marcar como atendida</button></div></div>`}
 }
 if(role==='residente'){
  const general=data.emergencyAlerts.find(item=>item.type==='General Portería'&&item.status==='Activa');
  if(general&&general.id!==dismissedGeneralAlertId)return `<div class="emergency-overlay general-overlay" role="alert"><span class="emergency-kicker">ALERTA GENERAL · PORTERÍA</span><h1>ATENCIÓN, RESIDENTES</h1><h2>Instrucciones de evacuación</h2><p>${esc(general.detail||'Siga las indicaciones de portería y evacúe por las rutas señalizadas.')}</p><small>${esc(general.date)}</small><button class="btn-attended" data-dismiss-general="${esc(general.id)}">Entendido</button></div>`;
  const success=data.emergencyAlerts.find(item=>item.id===panicSuccessAlertId&&item.status==='Activa');
  if(success)return `<div class="panic-success-overlay" role="status"><div class="success-check">✓</div><span class="eyebrow">SOLICITUD ENVIADA</span><h1>¡AYUDA EN CAMINO!</h1><p>El guardia va hacia ${esc(success.unit)}.</p><button class="btn-secondary" data-dismiss-panic-success>Volver al inicio</button></div>`;
 }
 return '';
}
function playEmergencySound(){try{const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return;const context=new AudioContextClass();for(let i=0;i<4;i++){const oscillator=context.createOscillator(),gain=context.createGain();oscillator.type='sawtooth';oscillator.frequency.value=i%2?660:880;gain.gain.value=.12;oscillator.connect(gain);gain.connect(context.destination);oscillator.start(context.currentTime+i*.42);oscillator.stop(context.currentTime+i*.42+.22)}setTimeout(()=>context.close(),2200)}catch{}}
