function resetPanicHold(button){
 if(!button)return;button.dataset.holding='false';button.classList.remove('is-holding');button.style.setProperty('--hold-progress','0deg');
 const label=button.querySelector('[data-panic-progress]');if(label)label.textContent='3 s';
 if(panicFrame)cancelAnimationFrame(panicFrame);panicFrame=0;
}
function beginPanicHold(button,event){
 if(!button||button.dataset.holding==='true')return;
 event?.preventDefault();button.dataset.holding='true';button.classList.add('is-holding');
 try{if(event?.pointerId!==undefined)button.setPointerCapture(event.pointerId)}catch{}
 const started=performance.now();
 const tick=now=>{
  if(button.dataset.holding!=='true'||!button.isConnected)return;
  const progress=Math.min(1,(now-started)/3000);button.style.setProperty('--hold-progress',`${progress*360}deg`);
  const label=button.querySelector('[data-panic-progress]');if(label)label.textContent=`${Math.max(0,Math.ceil((3000-(now-started))/1000))} s`;
  if(progress>=1){button.dataset.holding='done';navigator.vibrate?.([180,80,180]);createResidentAlert().catch(error=>notify(`No se pudo enviar la alerta: ${error.message}`));return}
  panicFrame=requestAnimationFrame(tick);
 };
 panicFrame=requestAnimationFrame(tick);
}
