async function openForm(action){
  if(action!=='question')activeAssemblyId='';
  activeAction=action;
  if(action==='request'&&livePortal()&&role==='residente'&&!requestsLoaded)await loadRequests();
  const f=forms[action];
  if(!f)return;
  $('#formTitle').textContent=f.title;
  $('#formEyebrow').textContent=f.desc;
  $('#formFields').innerHTML=f.fields.map(([id,label,type,placeholder])=>{
    let control;
    if(type==='select'){
      control=`<select id="field_${id}" required>${placeholder.split('|').map(option=>`<option>${option}</option>`).join('')}</select>`;
    }else if(type==='textarea'){
      control=`<textarea id="field_${id}" placeholder="${esc(placeholder)}" ${id==='description'&&action==='request'||id==='question'&&action==='question'?'required':''}></textarea>`;
    }else{
      const decimalInput=action==='property'&&id==='coeficiente';
      control=`<input id="field_${id}" type="${type}" ${decimalInput?'inputmode="decimal" pattern="[0-9]+([.,][0-9]+)?"':''} ${type==='number'?'step="any" min="0"':''} placeholder="${esc(placeholder)}" ${['title','name','unit'].includes(id)||action==='property'&&['identificador','coeficiente'].includes(id)||action==='assembly'&&['date','time'].includes(id)||action==='question'&&id==='options'?'required':''}>`;
    }
    return `<div class="field"><label for="field_${id}">${label}</label>${control}</div>`;
  }).join('');
  const formError=document.createElement('p');formError.className='auth-error';formError.id='actionFormError';formError.hidden=true;formError.setAttribute('role','alert');$('#formFields').prepend(formError);
  if(action==='request'&&livePortal()&&role==='residente'){
    const typeSelect=$('#field_type');
    if(typeSelect)typeSelect.innerHTML=requestTypes.map(type=>`<option value="${esc(type.code||type.name)}">${esc(type.name)}</option>`).join('');
    const unitField=document.createElement('div');unitField.className='field';unitField.innerHTML=`<label for="field_inmueble_id">Inmueble relacionado</label><select id="field_inmueble_id" required>${requestHomes.map(home=>`<option value="${esc(home.id)}">${esc(home.label)}</option>`).join('')||'<option value="">No hay inmueble asociado a tu perfil</option>'}</select>`;
    $('#field_description').closest('.field').before(unitField);
  }
  if(action==='question'){
    const optionInput=$('#field_options'),approval=document.createElement('div');approval.className='field';approval.innerHTML='<label for="field_approvingOption">Opción que significa “Aprobada”</label><select id="field_approvingOption"><option value="">No es una pregunta de aprobación</option></select><small class="muted">Selecciona la opción que aprueba la propuesta. Para una pregunta de consulta, deja la opción predeterminada.</small>';
    optionInput.closest('.field').after(approval);
    const refreshOptions=()=>{const select=$('#field_approvingOption'),current=select.value,options=optionInput.value.split('|').map(value=>value.trim()).filter(Boolean);select.innerHTML='<option value="">No es una pregunta de aprobación</option>'+options.map(option=>`<option value="${esc(option)}">${esc(option)}</option>`).join('');if(options.includes(current))select.value=current};
    optionInput.addEventListener('input',refreshOptions);refreshOptions();
  }
  if(action==='visitor'&&livePortal()&&role==='residente')await window.portalVisitorsPrepareForm?.();
  if(action==='reservation'&&livePortal()&&role==='residente')await window.portalLoansPrepareForm?.();
  $('#formDialog').showModal();
}
