function openUserForm(user=null){activeUserId=user?.id||'';openForm('user');const typeSelect=$('#field_tipo_residente'),homeSelect=$('#field_inmueble_id'),homeField=homeSelect.closest('.field'),roleSelect=$('#field_rol');typeSelect.outerHTML=`<div id="field_tipo_residente" class="user-type-options">${residentTypes.map(type=>`<label><input type="checkbox" name="userResidentType" value="${esc(type.codigo)}"> ${esc(type.nombre)}</label>`).join('')}</div>`;homeSelect.outerHTML=`<div id="field_inmueble_ids" class="user-property-options">${propertyRows.map(home=>`<label><input type="checkbox" name="userProperty" value="${esc(home.id)}"> ${esc(home.identificador)}</label>`).join('')||'<small>No hay inmuebles registrados.</small>'}<small>Los tipos seleccionados se aplicarán a todos los inmuebles marcados.</small></div>`;homeField.querySelector('label').htmlFor='field_inmueble_ids';const choices=[...document.querySelectorAll('[name="userResidentType"]')];if(user){for(const key of ['nombre_completo','email','telefono','rol']){const input=$(`#field_${key}`);if(input)input.value=user[key]||''}const relations=userRelations.filter(relation=>relation.usuario_id===user.id);const linkedHomes=new Set(relations.map(relation=>relation.inmueble_id));if(!linkedHomes.size&&user.inmueble_id)linkedHomes.add(user.inmueble_id);document.querySelectorAll('[name="userProperty"]').forEach(choice=>choice.checked=linkedHomes.has(choice.value));let selected=[...new Set(relations.map(relation=>relation.tipo_residente_codigo))];if(!selected.length){const legacy=residentTypes.find(type=>type.nombre===user.tipo_residente||type.codigo===user.tipo_residente);if(legacy)selected=[legacy.codigo]}choices.forEach(choice=>choice.checked=selected.includes(choice.value));const email=$('#field_email');email.disabled=true;email.closest('.field').hidden=true;$('#formTitle').textContent='Editar usuario';$('#formEyebrow').textContent='Actualiza el perfil y sus inmuebles asociados. No se enviará invitación.';$('#submitAction').textContent='Guardar cambios'}else{$('#field_email').disabled=false;$('#field_email').closest('.field').hidden=false;$('#submitAction').textContent='Enviar invitación'}const updateResidentFields=()=>{const resident=roleSelect.value==='Residente';document.querySelector('#field_tipo_residente').hidden=!resident;document.querySelector('#field_inmueble_ids').closest('.field').hidden=!resident;document.querySelectorAll('[name="userProperty"]').forEach(input=>input.required=false)};roleSelect.onchange=updateResidentFields;updateResidentFields()}
