$('#actionForm').addEventListener('submit',async e=>{
  if(e.submitter?.value==='cancel')return;
  e.preventDefault();
  const v=id=>$('#field_'+id)?.value?.trim()||'';
  if(livePortal()&&activeAction==='visitor'&&role==='residente'){await window.portalVisitorCreate?.();return}
  if(livePortal()&&activeAction==='reservation'&&role==='residente'){await window.portalLoanCreate?.();return}
  if(livePortal()&&activeAction==='notice'&&role==='administrador'){
    const saved=await window.portalNoticeCreate?.(v('title'),v('description'));
    if(saved){$('#formDialog').close();render()}
    return;
  }
  if(livePortal()&&activeAction==='incident'&&role==='vigilante'){
    await window.portalIncidentsSave?.({title:v('title'),unit:v('unit'),description:v('description')});
    return;
  }
  if(livePortal()&&(activeAction==='assembly'||activeAction==='question')){const values={title:v('title'),date:v('date'),time:v('time'),question:v('question'),options:v('options'),approvingOption:v('approvingOption')};await window.portalAssemblySave?.(activeAction,values,activeAssemblyId);return}
  if(livePortal()&&activeAction==='requestAdmin'){
    if(role!=='administrador'){notify('Solo administración puede actualizar las solicitudes.');return}
    const {error}=await window.portalSupabase.from('pqrs').update({estado:v('status'),respuesta_administracion:v('response')||null,actualizado_en:new Date().toISOString()}).eq('id',activeRequestId);
    if(error){showFormError(`No se pudo actualizar la solicitud: ${error.message}`);return}
    $('#formDialog').close();activeRequestId='';requestsLoaded=false;await loadRequests();notify('Solicitud y respuesta guardadas en Supabase');return;
  }
  if(livePortal()&&activeAction==='request'){
    if(role!=='residente'){notify('Solo un residente puede crear una solicitud.');return}
    const type=requestTypes.find(item=>item.code===v('type')||item.name===v('type'));const inmuebleId=v('inmueble_id');
    if(!type||!inmuebleId){showFormError('Selecciona el inmueble y el tipo de solicitud.');return}
    const {error}=await window.portalSupabase.from('pqrs').insert({usuario_id:authProfile.id,inmueble_id:inmuebleId,asunto:v('title'),tipo_pqr:type.name,tipo_pqr_codigo:type.code||null,descripcion:v('description'),estado:'Abierto',fecha_creacion:new Date().toISOString()});
    if(error){showFormError(`No se pudo enviar la solicitud: ${error.message}`);return}
    $('#formDialog').close();page='solicitudes';filter='Todos';requestsLoaded=false;await loadRequests();notify('Solicitud enviada a administración');return;
  }
  if(activeAction==='property'){
    if(role!=='administrador'||!livePortal()){notify('Inicia sesión como administrador para guardar inmuebles.');return}
    const coefficientText=v('coeficiente').replace(',','.');
    const coefficient=Number(coefficientText);
    if(!coefficientText||!Number.isFinite(coefficient)||coefficient<0){notify('Ingresa un coeficiente decimal válido, por ejemplo 0,96.');return}
    const property={identificador:v('identificador'),coeficiente:coefficient,tipo_unidad:v('tipo_unidad')||null,bloque:v('bloque')||null,numero:v('numero')||null};
    const query=activePropertyId?window.portalSupabase.from('inmuebles').update(property).eq('id',activePropertyId):window.portalSupabase.from('inmuebles').insert(property);
    const {error}=await query;
    if(error){notify(`No se pudo guardar el inmueble: ${error.message}`);return}
    $('#formDialog').close();activePropertyId='';page='inmuebles';await loadProperties();notify('Inmueble guardado en Supabase');return;
  }
  if(activeAction==='user'){
    if(role!=='administrador'||!livePortal()){notify('Inicia sesión como administrador para gestionar usuarios.');return}
    const userRole=v('rol'),typeCodes=[...document.querySelectorAll('[name="userResidentType"]:checked')].map(input=>input.value),selectedTypes=residentTypes.filter(item=>typeCodes.includes(item.codigo)),inmuebleIds=[...document.querySelectorAll('[name="userProperty"]:checked')].map(input=>input.value);
    if(userRole==='Residente'&&(!selectedTypes.length||!inmuebleIds.length)){notify('Selecciona al menos un tipo de residente y uno o más inmuebles.');return}
    if(activeUserId){
      const user=userRows.find(item=>item.id===activeUserId);if(user?.rol==='Administrador'&&userRole!=='Administrador'&&userRows.filter(item=>item.rol==='Administrador'&&item.activo!==false).length<=1){notify('No puedes cambiar el rol del último administrador activo.');return}const profile={nombre_completo:v('nombre_completo'),telefono:v('telefono')||null,rol:userRole,tipo_residente:userRole==='Residente'?selectedTypes[0].nombre:null,inmueble_id:userRole==='Residente'?inmuebleIds[0]:null};
      const {error}=await window.portalSupabase.from('usuarios').update(profile).eq('id',activeUserId);if(error){notify(`No se pudo actualizar el perfil: ${error.message}`);return}
      const {error:removeError}=await window.portalSupabase.from('inmueble_usuarios').delete().eq('usuario_id',activeUserId);if(removeError){notify(`El perfil se actualizó, pero no se pudo actualizar la asociación: ${removeError.message}`);return}
      if(userRole==='Residente'){const links=inmuebleIds.flatMap(inmueble_id=>selectedTypes.map(item=>({inmueble_id,usuario_id:activeUserId,tipo_residente_codigo:item.codigo})));const {error:linkError}=await window.portalSupabase.from('inmueble_usuarios').insert(links);if(linkError){notify(`El perfil se guardó, pero falló la asociación: ${linkError.message}`);return}}
      $('#formDialog').close();notify('Perfil de usuario actualizado');usersLoaded=false;await loadUsers();return;
    }
    const {error}=await window.portalSupabase.functions.invoke('admin-users',{body:{nombre_completo:v('nombre_completo'),email:v('email'),telefono:v('telefono'),rol:userRole,tipo_residente_codigos:userRole==='Residente'?typeCodes:[],inmueble_ids:userRole==='Residente'?inmuebleIds:[]}});
    if(error){let message=error.message;try{const payload=await error.context?.json();if(payload?.error)message=payload.error}catch{}notify(`No se pudo invitar al usuario: ${message}`);return}
    $('#formDialog').close();notify('Invitación enviada al correo y perfil creado');usersLoaded=false;await loadUsers();return;
  }
  if(activeAction==='request'){data.requests.unshift({id:`SOL-${String(250+data.requests.length).padStart(4,'0')}`,title:v('title'),type:v('type'),unit:'Torre 2 · 504',date:'Hoy, ahora',status:'Pendiente'});page='solicitudes'}
  if(activeAction==='visitor'){data.visitors.unshift({name:v('name'),unit:v('unit'),kind:v('kind'),date:'Hoy, por confirmar',status:'Esperado',code:`V-${Math.floor(1000+Math.random()*8999)}`});page='visitantes'}
  if(activeAction==='incident'){data.incidents.unshift({title:v('title'),unit:v('unit'),date:'Hoy, ahora',status:'Pendiente'});page='novedades'}
  if(activeAction==='notice'){data.notices.unshift({title:v('title'),text:v('description'),date:'21 oct · Administración',icon:'✦'});page='comunicados'}
  if(activeAction==='reservation'){data.reservations.unshift({title:v('title'),unit:role==='residente'?'Torre 2 · 504':'Administración',date:v('date')||'Fecha por confirmar',status:'En revisión'});page='reservas'}
  if(activeAction==='package'){notify('Paquete registrado y residente notificado');$('#formDialog').close();return}
  if(activeAction==='assembly'){data.assemblies.unshift({id:`ASM-${Date.now()}`,title:v('title'),date:v('date'),time:v('time'),status:'Planificada',attendance:{},questions:[]});page='asambleas'}
  if(activeAction==='question'){
    const assembly=data.assemblies.find(item=>item.id===activeAssemblyId);
    const options=v('options').split('|').map(option=>option.trim()).filter(Boolean);
    if(!assembly){notify('No se encontró la asamblea seleccionada');return}
    if(options.length<2||new Set(options.map(option=>option.toLowerCase())).size!==options.length){notify('Agrega al menos dos opciones diferentes separadas por |');return}
    assembly.questions.push({id:`Q-${Date.now()}`,text:v('question'),options,status:'Cerrada',votes:{}});
    page='asambleas';
  }
  save();$('#formDialog').close();render();notify('Información guardada correctamente');
});
