function bindAssemblyControls(){if(livePortal())return;document.querySelectorAll('[data-question-state]').forEach(button=>{button.onclick=()=>{if(role!=='administrador')return;const assembly=data.assemblies.find(item=>item.id===button.dataset.assembly);const question=assembly?.questions.find(item=>item.id===button.dataset.questionId);const next=button.dataset.nextState;if(!assembly||!question){notify('No se encontró la pregunta de esta asamblea');return}if(next==='Activa'&&assembly.status==='Finalizada'){notify('No puedes activar preguntas de una asamblea finalizada');return}if(next==='Activa')assembly.questions.forEach(item=>item.status='Cerrada');question.status=next;save();render();notify(next==='Activa'?'Pregunta activada':'Pregunta cerrada')}})}


function clockWidget(){
  return `<span class="weather" title="Hora local de La Mesa">◷ <span id="localClockValue">${localClock()}</span></span><small>Hora local<br>La Mesa, Cundinamarca</small>`;
}
function localClock(){
  return new Intl.DateTimeFormat('es-CO',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:'America/Bogota'}).format(new Date());
}
setInterval(()=>{
  const clock=document.getElementById('localClockValue');
  if(clock)clock.textContent=localClock();
},15*1000);
